@page{margin:34px 42px}*{box-sizing:border-box}body{font-family:DejaVu Sans,sans-serif;color:#172321;font-size:10px;line-height:1.45}.brand{font-weight:bold;font-size:16px}.brand b{display:inline-block;background:#f2765e;color:white;padding:5px 9px;border-radius:5px;margin-right:7px}.top{width:100%;border-bottom:2px solid #172321;padding-bottom:22px}.top td:last-child{text-align:right}.kicker{font-size:8px;color:#7a8581;text-transform:uppercase;letter-spacing:1px}.title{font-family:DejaVu Serif,serif;font-size:26px;margin:8px 0 3px}.status{display:inline-block;background:#e7f1ed;color:#2d755b;padding:4px 8px;border-radius:10px;font-size:8px}.parties{width:100%;margin:25px 0}.parties td{width:50%;vertical-align:top}.parties strong{display:block;font-size:12px;margin:7px 0 3px}.items{width:100%;border-collapse:collapse}.items th{text-align:left;border-bottom:1px solid #172321;padding:8px 5px;font-size:8px;text-transform:uppercase}.items td{padding:11px 5px;border-bottom:1px solid #e4e1d9}.items td:not(:first-child),.items th:not(:first-child){text-align:right}.summary{width:45%;margin:18px 0 0 auto;border-collapse:collapse}.summary td{padding:5px}.summary td:last-child{text-align:right;font-weight:bold}.summary .grand td{border-top:1px solid #172321;padding-top:10px;font-size:15px;font-family:DejaVu Serif,serif}.note{margin-top:26px;border-top:1px solid #e4e1d9;padding-top:14px}.note h3{font-family:DejaVu Serif,serif;margin:0 0 6px;font-size:13px}.footer{position:fixed;bottom:-12px;left:0;right:0;text-align:center;color:#9aa19f;font-size:8px}
